// src/store.ts
import { configureStore, createSlice, PayloadAction } from '@reduxjs/toolkit';

// ============================================
// AUTH SLICE (Everything in one file)
// ============================================

interface AuthState {
  isAuthenticated: boolean;
  username: string | null;
  balance: number;
  loading: boolean;
  error: string | null;
}

const initialAuthState: AuthState = {
  isAuthenticated: false,
  username: null,
  balance: 0,
  loading: false,
  error: null,
};

const authSlice = createSlice({
  name: 'auth',
  initialState: initialAuthState,
  reducers: {
    loginStart: (state) => {
      state.loading = true;
      state.error = null;
    },
    loginSuccess: (state, action: PayloadAction<{ username: string; balance: number }>) => {
      state.isAuthenticated = true;
      state.username = action.payload.username;
      state.balance = action.payload.balance;
      state.loading = false;
      state.error = null;
    },
    loginFailure: (state, action: PayloadAction<string>) => {
      state.loading = false;
      state.error = action.payload;
    },
    logout: (state) => {
      state.isAuthenticated = false;
      state.username = null;
      state.balance = 0;
      state.loading = false;
      state.error = null;
    },
    updateBalance: (state, action: PayloadAction<number>) => {
      state.balance += action.payload;
    },
    clearError: (state) => {
      state.error = null;
    },
  },
});

// ============================================
// GAMES SLICE (Also in same file)
// ============================================

interface Game {
  id: string;
  name: string;
  image: string;
  category: string;
}

interface GamesState {
  games: Game[];
  currentGame: string | null;
  loading: boolean;
}

const initialGamesState: GamesState = {
  games: [],
  currentGame: null,
  loading: false,
};

const gamesSlice = createSlice({
  name: 'games',
  initialState: initialGamesState,
  reducers: {
    setGames: (state, action: PayloadAction<Game[]>) => {
      state.games = action.payload;
      state.loading = false;
    },
    setCurrentGame: (state, action: PayloadAction<string>) => {
      state.currentGame = action.payload;
    },
    setLoading: (state, action: PayloadAction<boolean>) => {
      state.loading = action.payload;
    },
  },
});

// ============================================
// UI SLICE (For loading indicators, modals, etc.)
// ============================================

interface UiState {
  isLoading: boolean;
  modal: string | null;
  theme: 'light' | 'dark';
}

const initialUiState: UiState = {
  isLoading: false,
  modal: null,
  theme: 'dark',
};

const uiSlice = createSlice({
  name: 'ui',
  initialState: initialUiState,
  reducers: {
    showLoading: (state) => {
      state.isLoading = true;
    },
    hideLoading: (state) => {
      state.isLoading = false;
    },
    openModal: (state, action: PayloadAction<string>) => {
      state.modal = action.payload;
    },
    closeModal: (state) => {
      state.modal = null;
    },
    toggleTheme: (state) => {
      state.theme = state.theme === 'light' ? 'dark' : 'light';
    },
  },
});

// ============================================
// EXPORT ALL ACTIONS
// ============================================

export const authActions = authSlice.actions;
export const gamesActions = gamesSlice.actions;
export const uiActions = uiSlice.actions;

// ============================================
// CREATE AND EXPORT THE STORE
// ============================================

export const store = configureStore({
  reducer: {
    auth: authSlice.reducer,
    games: gamesSlice.reducer,
    ui: uiSlice.reducer,
  },
});

// ============================================
// EXPORT TYPES
// ============================================

export type RootState = ReturnType<typeof store.getState>;
export type AppDispatch = typeof store.dispatch;

// ============================================
// OPTIONAL: TYPED HOOKS
// ============================================

import { useDispatch, useSelector, TypedUseSelectorHook } from 'react-redux';

export const useAppDispatch: () => AppDispatch = useDispatch;
export const useAppSelector: TypedUseSelectorHook<RootState> = useSelector;
